using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using AICad.Contracts;
using Newtonsoft.Json.Linq;
namespace AICad.Application;
public sealed class WarehouseService(InstallConfig config,WorkspaceService workspace){
 public JObject State(){string path=config.ContentRoot;try{path=WarehousePaths.Resolve(config.ContentRoot);bool shared=File.Exists(Path.Combine(path,"warehouse.json"));var store=new ContentStore(path);return JObject.FromObject(new{path,connected=true,shared,templates=store.Ids("templates").Count(id=>!WarehousePaths.IsRetired(path,"templates",id)&&!new LibraryCatalog(path).Deleted("templates",id)),skills=store.Ids("skills").Count(id=>!WarehousePaths.IsRetired(path,"skills",id)&&!new LibraryCatalog(path).Deleted("skills",id)),message=shared?"Kho đã kết nối":"Đang dùng thư viện trong app"});}catch(Exception e)when(e is IOException||e is CadException||e is UnauthorizedAccessException){string pointer=Path.Combine(config.ContentRoot,"warehouse.local.json");try{if(File.Exists(pointer))path=Json.Read<JObject>(File.ReadAllText(pointer)).Value<string>("path")??path;}catch(Exception parse)when(parse is IOException||parse is CadException){}return JObject.FromObject(new{path,connected=false,shared=true,message=e.Message});}}
 public JObject Check(string path){path=Path.GetFullPath(path);WarehousePaths.Validate(path);var store=new ContentStore(path);int blocks=0;var hashes=new HashSet<string>();foreach(string id in store.Ids("templates")){foreach(string v in store.Versions("templates",id)){var t=store.Template(id,v);foreach(var b in t.Blocks.Where(b=>b.NativeSource!=null))hashes.Add(b.NativeSource!.FileHash);}if(!WarehousePaths.IsRetired(path,"templates",id)&&!new LibraryCatalog(path).Deleted("templates",id))blocks+=store.Template(id).Blocks.Count;}foreach(string id in store.Ids("skills")){foreach(string v in store.Versions("skills",id))_ = store.Skill(id,v);var s=store.Skill(id);_ = store.Template(s.TemplateId);}foreach(string hash in hashes){string file=Path.Combine(WarehousePaths.InRoot(path,"content-assets"),hash+".dwg");if(!File.Exists(file)||Json.FileHash(file)!=hash)throw new CadException("WAREHOUSE_ASSET_MISSING","Thiếu hoặc sai DWG: "+hash);}return JObject.FromObject(new{path,connected=true,templates=store.Ids("templates").Count(id=>!WarehousePaths.IsRetired(path,"templates",id)&&!new LibraryCatalog(path).Deleted("templates",id)),skills=store.Ids("skills").Count(id=>!WarehousePaths.IsRetired(path,"skills",id)&&!new LibraryCatalog(path).Deleted("skills",id)),blocks,assets=hashes.Count,message="Đã kiểm tra phiên bản và mã kiểm tra tài nguyên"});}
 public JObject Select(string path){if(Uri.TryCreate(path,UriKind.Absolute,out var uri)&&uri.Scheme.StartsWith("http"))throw new CadException("WAREHOUSE_PATH","Chọn thư mục Google Drive đã đồng bộ, không dán link web.");var checkedRoot=Check(path);string? current=null;try{current=WarehousePaths.Resolve(config.ContentRoot);}catch(CadException){}if(string.Equals(current,Path.GetFullPath(path),StringComparison.OrdinalIgnoreCase))return checkedRoot;if(workspace.Cad.Sessions().Any(s=>!Version.TryParse(s.PluginVersion,out var v)||v<new Version(0,5,0)))throw new CadException("PLUGIN_UPDATE_REQUIRED","Lưu bản vẽ và mở lại AutoCAD bằng plugin mới trước khi đổi kho.");foreach(var p in workspace.History().Where(p=>p.Status=="READY"||p.Status=="PREVIEW"))workspace.Cancel(p.Plan.PlanId);WarehousePaths.Select(config.ContentRoot,path);return checkedRoot;}
 public JObject Refresh(){string path=WarehousePaths.Resolve(config.ContentRoot);var result=Check(path);var store=new ContentStore(path);var catalog=new{schemaVersion=1,updatedUtc=DateTime.UtcNow,templates=store.Ids("templates").Where(id=>!WarehousePaths.IsRetired(path,"templates",id)&&!new LibraryCatalog(path).Deleted("templates",id)).Select(id=>{var t=store.Template(id);return new{t.Id,t.Name,t.Version,versions=store.Versions("templates",id),blocks=t.Blocks.Select(b=>new{b.Id,b.NativeSource})};}).ToArray(),skills=store.Ids("skills").Where(id=>!WarehousePaths.IsRetired(path,"skills",id)&&!new LibraryCatalog(path).Deleted("skills",id)).Select(id=>store.Skill(id)).ToArray()};Json.Atomic(Path.Combine(path,"Catalog","index.json"),catalog);return result;}
 public JObject Migrate(string path){if(System.Diagnostics.Process.GetProcessesByName("acad").Length>0)throw new CadException("CLOSE_AUTOCAD","Lưu và đóng AutoCAD trước khi chuyển kho lần đầu.");path=Path.GetFullPath(path);if(path.Equals(config.ContentRoot,StringComparison.OrdinalIgnoreCase)||path.StartsWith(config.ContentRoot+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new CadException("WAREHOUSE_PATH","Chọn thư mục kho nằm ngoài thư mục app.");if(Directory.Exists(path)&&Directory.EnumerateFileSystemEntries(path).Any())throw new CadException("WAREHOUSE_EXISTS","Thư mục đích phải trống. Dùng Kết nối nếu kho đã tồn tại.");Directory.CreateDirectory(path);Json.Atomic(Path.Combine(path,"warehouse.json"),new{schemaVersion=1,name="Kho AI CAD",createdUtc=DateTime.UtcNow});foreach(string name in new[]{"CAD/Assets","CAD/Originals","Templates","Skills","Versions","Sources/Files","Sources/Catalog","Approved-Samples","Catalog"})Directory.CreateDirectory(Path.Combine(path,name));
  foreach(string kind in new[]{"packages","skills","template-library","content-assets"}){string source=WarehousePaths.Folder(config.ContentRoot,kind),target=WarehousePaths.InRoot(path,kind);if(!Directory.Exists(source))continue;foreach(string file in Directory.EnumerateFiles(source,"*",SearchOption.AllDirectories)){string dest=Path.Combine(target,Path.GetRelativePath(source,file));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(file,dest,false);if(Json.FileHash(file)!=Json.FileHash(dest))throw new CadException("COPY_FAILED","Tệp sao chép không khớp: "+file);}}
  string oldCatalog=Path.Combine(WarehousePaths.Resolve(config.ContentRoot),"Catalog");if(Directory.Exists(oldCatalog))foreach(string file in Directory.EnumerateFiles(oldCatalog,"*",SearchOption.AllDirectories)){string dest=Path.Combine(path,"Catalog",Path.GetRelativePath(oldCatalog,file));Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.Copy(file,dest,false);if(Json.FileHash(file)!=Json.FileHash(dest))throw new CadException("COPY_FAILED","Danh mục sao chép không khớp.");}
  _ = Check(path);WarehousePaths.Select(config.ContentRoot,path);ArchiveLocalSources();_ = Refresh();string backup=Path.Combine(config.DataRoot,"warehouse-before-move-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss"));foreach(string kind in new[]{"packages","skills","template-library","content-assets"}){string old=Path.Combine(config.ContentRoot,kind);if(!Directory.Exists(old))continue;Directory.CreateDirectory(backup);Directory.Move(old,Path.Combine(backup,kind));}return JObject.FromObject(new{path,connected=true,backup,status="MIGRATED"});
 }
 public void ArchiveSource(string id){Json.Id(id);string root=WarehousePaths.Resolve(config.ContentRoot);if(!File.Exists(Path.Combine(root,"warehouse.json")))return;string local=Path.Combine(config.DataRoot,"sources"),metaFile=Path.Combine(local,id+".json");var meta=Json.Read<JObject>(File.ReadAllText(metaFile));string ext=Path.GetExtension(meta.Value<string>("name")??"").ToLowerInvariant();if(!new[]{".pdf",".png",".jpg",".jpeg"}.Contains(ext))return;string hash=meta.Value<string>("hash")??"",original=Path.Combine(local,id+ext);if(!File.Exists(original)||Json.FileHash(original)!=hash)throw new CadException("SOURCE_CHANGED","Nguồn cục bộ đã thay đổi.");string dest=Path.Combine(root,"Sources","Files",hash+ext);Directory.CreateDirectory(Path.GetDirectoryName(dest)!);if(!File.Exists(dest))File.Copy(original,dest);if(Json.FileHash(dest)!=hash)throw new CadException("SOURCE_CHANGED","Nguồn trong kho không khớp.");var shared=new JObject{["id"]=id,["name"]=meta["name"]?.DeepClone(),["hash"]=hash,["size"]=meta["size"]?.DeepClone(),["extension"]=ext};string analysis=Path.Combine(local,id+".analysis.json");if(File.Exists(analysis)){var m=Json.Read<JObject>(File.ReadAllText(analysis));if(m["calibration"]?.Value<bool?>("confirmed")==true)shared["calibration"]=m["calibration"]!.DeepClone();if(m["reviewMetadata"] is JObject r)shared["imageSize"]=new JObject{["widthMm"]=r["widthMm"]?.DeepClone(),["heightMm"]=r["heightMm"]?.DeepClone(),["imageRect"]=r["imageRect"]?.DeepClone()};}Json.Atomic(Path.Combine(root,"Sources","Catalog",id+".json"),shared);}
 public void ArchiveLocalSources(){string folder=Path.Combine(config.DataRoot,"sources");if(!Directory.Exists(folder))return;foreach(string file in Directory.EnumerateFiles(folder,"*.json")){string id=Path.GetFileNameWithoutExtension(file);if(Guid.TryParseExact(id,"N",out _))ArchiveSource(id);}}
 public List<JObject> Sources(){string folder=Path.Combine(WarehousePaths.Resolve(config.ContentRoot),"Sources","Catalog");return Directory.Exists(folder)?Directory.EnumerateFiles(folder,"*.json").Select(f=>Json.Read<JObject>(File.ReadAllText(f))).ToList():new();}
 public JObject ImportSource(string id){Json.Id(id);string root=WarehousePaths.Resolve(config.ContentRoot);var m=Json.Read<JObject>(File.ReadAllText(Path.Combine(root,"Sources","Catalog",id+".json")));string ext=m.Value<string>("extension")??"";if(!new[]{".pdf",".png",".jpg",".jpeg"}.Contains(ext))throw new CadException("INVALID_SOURCE","Định dạng nguồn không hỗ trợ.");string hash=m.Value<string>("hash")??"";if(!System.Text.RegularExpressions.Regex.IsMatch(hash,"^[a-f0-9]{64}$"))throw new CadException("INVALID_SOURCE","Mã nguồn không hợp lệ.");string source=Path.Combine(root,"Sources","Files",hash+ext);if(Json.FileHash(source)!=hash)throw new CadException("SOURCE_CHANGED","Tệp nguồn trong kho đã thay đổi.");string local=Path.Combine(config.DataRoot,"sources");Directory.CreateDirectory(local);string target=Path.Combine(local,id+ext);if(File.Exists(target)&&Json.FileHash(target)!=hash)throw new CadException("SOURCE_CONFLICT","ID nguồn đã có tệp khác trên máy này.");if(!File.Exists(target))File.Copy(source,target);string metadata=Path.Combine(local,id+".json");if(!File.Exists(metadata))Json.Atomic(metadata,new{id,name=m.Value<string>("name"),hash,size=new FileInfo(source).Length,status="NEEDS_CALIBRATION",message="Đã lấy nguồn từ kho; cần kiểm tra và dựng kế hoạch trên máy này."});return m;}
}
